// Puts the logo (app/design/logo.svg, generated by app/design/logo.py) into
// the Icon Composer package as a vector layer, and renders the website's
// PNGs from it. macOS 26 draws the glass, tinted and clear looks from the
// vector itself; Xcode generates the legacy sizes for macOS 14/15.
// Usage: swift app/tools/make-icon.swift <logo.svg> <AppIcon.icon dir> <site public dir>
import AppKit

let args = CommandLine.arguments
guard args.count == 4, let logo = NSImage(contentsOfFile: args[1]) else {
    FileHandle.standardError.write("usage: make-icon.swift <logo.svg> <AppIcon.icon> <public dir>\n".data(using: .utf8)!)
    exit(1)
}
let fm = FileManager.default

// 1. The icon layer: the SVG itself, so nothing is rasterised.
let assets = args[2] + "/Assets"
try! fm.createDirectory(atPath: assets, withIntermediateDirectories: true)
for old in (try? fm.contentsOfDirectory(atPath: assets)) ?? [] {
    try! fm.removeItem(atPath: assets + "/" + old)
}
try! fm.copyItem(atPath: args[1], toPath: assets + "/logo.svg")
print("wrote \(assets)/logo.svg")

// 2. Site images: the mark on the ink tile of the icon (#141c26), as the
// browser tab, header, touch icon and link preview show it.
let ink = NSColor(srgbRed: 0x14 / 255.0, green: 0x1c / 255.0, blue: 0x26 / 255.0, alpha: 1)

func render(_ size: Int, rounded: Bool, to name: String) {
    let rep = NSBitmapImageRep(bitmapDataPlanes: nil, pixelsWide: size, pixelsHigh: size, bitsPerSample: 8,
                               samplesPerPixel: 4, hasAlpha: true, isPlanar: false, colorSpaceName: .deviceRGB,
                               bytesPerRow: 0, bitsPerPixel: 0)!
    NSGraphicsContext.saveGraphicsState()
    NSGraphicsContext.current = NSGraphicsContext(bitmapImageRep: rep)
    NSGraphicsContext.current!.imageInterpolation = .high
    let rect = NSRect(x: 0, y: 0, width: size, height: size)
    ink.setFill()
    // Apple's icon corner is about 22.5% of the side; iOS rounds touch icons itself.
    (rounded ? NSBezierPath(roundedRect: rect, xRadius: CGFloat(size) * 0.225, yRadius: CGFloat(size) * 0.225)
             : NSBezierPath(rect: rect)).fill()
    logo.draw(in: rect)
    NSGraphicsContext.restoreGraphicsState()
    let out = args[3] + "/" + name
    try! rep.representation(using: .png, properties: [:])!.write(to: URL(fileURLWithPath: out))
    print("wrote \(out)")
}

render(64, rounded: true, to: "favicon.png")
render(64, rounded: true, to: "logo-64.png")
render(96, rounded: true, to: "logo-96.png")
render(192, rounded: true, to: "logo-192.png")
render(930, rounded: true, to: "logo.png")
render(180, rounded: false, to: "apple-touch-icon.png")
